# A signature and its twin with s replaced by n - s
signature = L.ecdsa_sign(K.SK, K.MSG)
r, s = L.der_parse_lax(signature)[:2]
twin = L.der_encode(r, L.N - s)
pk = L.pubkey_create(K.SK)

def is_valid(sig):
    return L.ecdsa_verify(pk, K.MSG, sig)

def is_low_s(sig):
    return L.is_low_s(sig + b'\x01')
# Both are valid; only the low-s form passes the relay policy
verdict = [(is_valid(g), is_low_s(g)) for g in (signature, twin)]
print(verdict)
